files.content:
@custom-variant dense (&:where(:root[data-density='dense'] *));

/* every name comes from the loom. the semantic colours are dyes. */
@theme {
  --font-ui: 'Archivo', ui-sans-serif, system-ui, sans-serif;
  --font-data: 'IBM Plex Mono', ui-monospace, SFMono-Regular, monospace;

  --color-ground: var(--p-ground);
  --color-raised: var(--p-raised);
  --color-sunken: var(--p-sunken);
  --color-shed: var(--p-shed);
  --color-reed: var(--p-reed);
  --color-reed-lit: var(--p-reed-lit);

  --color-weft: var(--p-weft);
  --color-weft-dim: var(--p-weft-dim);
  --color-weft-faint: var(--p-weft-faint);

  --color-indigo: var(--p-indigo);
  --color-indigo-wash: var(--p-indigo-wash);
  --color-jade: var(--p-jade);
  --color-madder: var(--p-madder);
  --color-weld: var(--p-weld);
  --color-logwood: var(--p-logwood);

  /* one pick is one pass of the weft, and the motif carries five of them */
  --color-pick-1: var(--p-indigo);
  --color-pick-2: var(--p-jade);
  --color-pick-3: var(--p-weld);
  --color-pick-4: var(--p-madder);
  --color-pick-5: var(--p-logwood);
}

/* the shed is the opening a loom makes and closes: the row under the pointer */
:root {
  --p-ground: #0b0d14;
  --p-raised: #12151f;
  --p-sunken: #070910;
  --p-shed: #191d29;
  --p-reed: #1c2030;
  --p-reed-lit: #2b3145;

  --p-weft: #e9e5db;
  --p-weft-dim: #9b9789;
  --p-weft-faint: #6a6759;

  --p-indigo: #5f72ef;
  --p-indigo-wash: #1a1f42;
  --p-jade: #4fa88b;
  --p-madder: #d2624f;
  --p-weld: #c9a227;
  --p-logwood: #9b6bd6;

  --shadow-layer: 0 18px 44px -16px rgb(0 0 0 / 0.62);
}

:root[data-theme='light'] {
  --p-ground: #f2f1ec;
  --p-raised: #faf9f5;
  --p-sunken: #e8e6df;
  --p-shed: #f1efe8;
  --p-reed: #dcd9d0;
  --p-reed-lit: #c2beb2;

  --p-weft: #14161d;
  --p-weft-dim: #5c594f;
  --p-weft-faint: #8a8779;

  --p-indigo: #3a49c4;
  --p-indigo-wash: #e4e5f7;
  --p-jade: #2f7a61;
  --p-madder: #b04430;
  --p-weld: #8a6f12;
  --p-logwood: #7a3f9e;

  --shadow-layer: 0 18px 44px -16px rgb(26 24 20 / 0.24);
}

/*
 * a control reads these and defines none of its own, so one attribute on the root
 * retunes the whole interface.
 */
:root,
:root[data-density='compact'] {
  --row-h: 32px;
  --cell-x: 10px;
  --ui-text: 13px;
  --ctl-h: 28px;
  --stack: 8px;
  --reed-pitch: 5px;
}

:root[data-density='comfortable'] {
  --row-h: 40px;
  --cell-x: 14px;
  --ui-text: 14px;
  --ctl-h: 34px;
  --stack: 10px;
  --reed-pitch: 6px;
}

:root[data-density='dense'] {
  --row-h: 25px;
  --cell-x: 7px;
  --ui-text: 12px;
  --ctl-h: 23px;
  --stack: 6px;
  --reed-pitch: 4px;
}

/*
 * a duration is named for what it moves. every layer that leaves the flow declares
 * its rank here: a sticky header makes a stacking context and paints over any layer
 * with no rank.
 */
:root {
  --reed-tick: 1px;
  --ctl-box: 13px;

  /*
   * vertical-align: middle centres on the x-height. every value here is digits and
   * capitals, so the band runs baseline to cap height. this is half the difference,
   * for the data face.
   */
  --ctl-lift: 0.091em;

  /* the advance of the data face. a column width can then be a character count. */
  --data-adv: 0.6em;

  --z-grip: 1;
  --z-pinned: 5;
  --z-sticky: 10;
  /* the panel keeps the page usable: a popover opened inside it paints above it */
  --z-panel: 20;
  --z-popover: 30;
  --z-backdrop: 40;
  --z-modal: 50;

  --dur-instant: 90ms;
  --dur-local: 160ms;
  --dur-overlay: 240ms;

  --ease-beat: cubic-bezier(0.2, 0.9, 0.24, 1);
  --ease-glide: cubic-bezier(0.33, 0, 0.15, 1);
  --ease-exit: cubic-bezier(0.5, 0, 0.9, 0.4);
}

@media (prefers-reduced-motion: reduce) {
  :root {
    --dur-instant: 0ms;
    --dur-local: 0ms;
    --dur-overlay: 0ms;
  }
}

@layer base {
  body {
    background-color: var(--color-ground);
    color: var(--color-weft);
    font-family: var(--font-ui);
    font-size: var(--ui-text);
    -webkit-font-smoothing: antialiased;
  }

  /* the second selector: a control whose focus lands on a child, like a field with an icon */
  :focus-visible,
  .focus-ring:has(:focus-visible) {
    outline: 2px solid var(--color-indigo);
    outline-offset: 1px;
  }

  ::selection {
    background-color: var(--color-indigo);
    color: #fff;
  }
}

@utility tnum {
  font-variant-numeric: tabular-nums;
}

/* a utility, for a state variant to dye a part that ark controls */
@utility selvedge-on {
  --selvedge: var(--color-indigo);
}

/*
 * ark positions its floating parts with an inline `z-index: var(--z-index)` beside
 * an inline `--z-index: auto`. an inline custom property outranks a stylesheet, so
 * this has to be important to reach it. parts ark does not position take a class.
 */
[data-part='positioner']:not([data-scope='dialog']) {
  --z-index: var(--z-popover) !important;
}

@layer components {
  /* the reed: the evenly spaced slots that hold the warp on a loom */
  .reed-edge {
    position: relative;
  }

  .reed-edge::after {
    content: '';
    position: absolute;
    inset-inline: 0;
    bottom: 0;
    height: 2px;
    background-image: repeating-linear-gradient(
      90deg,
      var(--color-reed-lit) 0 var(--reed-tick),
      transparent var(--reed-tick) var(--reed-pitch)
    );
  }

  /*
   * the same pitch turned a quarter. a cell takes the leading line and a pinned cell
   * takes the trailing one: the next cell's leading line travels away under it.
   */
  .warp-line,
  .warp-line-end {
    position: relative;
  }

  .warp-line::before,
  .warp-line-end::before {
    content: '';
    position: absolute;
    inset-block: 0;
    width: 1px;
    background-image: repeating-linear-gradient(
      0deg,
      var(--color-reed) 0 var(--reed-tick),
      transparent var(--reed-tick) var(--reed-pitch)
    );
  }

  /* under the digits, never on the divider: a divider cannot name which value is low */
  .reed-under {
    background-image: repeating-linear-gradient(
      90deg,
      var(--color-madder) 0 var(--reed-tick),
      transparent var(--reed-tick) var(--reed-pitch)
    );
    background-position: bottom;
    background-size: 100% 1px;
    background-repeat: no-repeat;
  }

  /* the selvedge is the finished edge of a cloth. it marks a choice; the shed marks a position. */
  .selvedge {
    position: relative;
    --selvedge: transparent;
  }

  .selvedge::after {
    content: '';
    position: absolute;
    inset-block: 0;
    inset-inline-start: 0;
    width: 2px;
    background-image: repeating-linear-gradient(
      0deg,
      var(--selvedge) 0 var(--reed-tick),
      transparent var(--reed-tick) var(--reed-pitch)
    );
  }

  /* the same edge turned a quarter, for a list of choices that runs across */
  .selvedge-bottom::after {
    inset-block: auto 0;
    inset-inline: 0;
    width: auto;
    height: 2px;
    background-image: repeating-linear-gradient(
      90deg,
      var(--selvedge) 0 var(--reed-tick),
      transparent var(--reed-tick) var(--reed-pitch)
    );
  }

  /*
   * a row cannot wear the base outline. its own cells paint over it, and a pinned cell
   * covers what is left, so all that survives is a fragment of the bottom edge. the ring
   * is drawn inside the cells instead, which is the one place a pinned cell cannot hide.
   */
  .focus-row:focus-visible {
    outline: none;
  }

  .focus-row:focus-visible > td {
    box-shadow:
      inset 0 2px 0 var(--color-indigo),
      inset 0 -2px 0 var(--color-indigo);
  }

  /* zag places the mark and reads these two names for the slide from tab to tab */
  .tab-mark {
    --transition-duration: var(--dur-local);
    --transition-timing-function: var(--ease-beat);
  }

  /* every surface that leaves the flow draws the same edge and the same shadow */
  .layer {
    border: 1px solid var(--color-reed-lit);
    background-color: var(--color-raised);
    box-shadow: var(--shadow-layer);
  }

  /*
   * zag gives a toast its offset, its height and its opacity as custom properties,
   * and the transition between two of its positions belongs to the stylesheet.
   */
  .toast {
    translate: var(--x) var(--y);
    height: var(--height, auto);
    opacity: var(--opacity);
    transition:
      translate var(--dur-overlay) var(--ease-beat),
      height var(--dur-overlay) var(--ease-beat),
      opacity var(--dur-overlay) var(--ease-beat);
    will-change: translate, opacity;
  }

  /*
   * three ticks, and the order of the heights is the direction. tighter than the
   * pitch, because a head reserves this width and a narrow column cannot pay a full one.
   */
  .reed-sort {
    display: inline-block;
    width: 7px;
    height: 7px;
    background-image:
      linear-gradient(currentColor, currentColor), linear-gradient(currentColor, currentColor),
      linear-gradient(currentColor, currentColor);
    background-size: var(--reed-tick) 3px, var(--reed-tick) 5px, var(--reed-tick) 7px;
    background-position: left bottom, center bottom, right bottom;
    background-repeat: no-repeat;
  }

  .reed-sort-down {
    background-size: var(--reed-tick) 7px, var(--reed-tick) 5px, var(--reed-tick) 3px;
  }

  /* a control beside a row of values aligns on the cap band */
  .ctl-align {
    vertical-align: middle;
    translate: 0 calc(-1 * var(--ctl-lift));
  }

  /* the surface that every control shares */
  .ctl {
    display: inline-flex;
    align-items: center;
    gap: 0.375rem;
    border: 1px solid var(--color-reed);
    background-color: var(--color-ground);
    padding-inline: var(--cell-x);
    color: var(--color-weft);
    transition: border-color var(--dur-instant) var(--ease-beat);
  }

  .ctl:hover {
    border-color: var(--color-reed-lit);
  }

  /* one tick of the reed stands where a value is absent */
  .reed-mark {
    display: inline-block;
    width: var(--reed-tick);
    height: var(--reed-pitch);
    background-color: var(--color-reed-lit);
    vertical-align: middle;
  }

  .warp-line::before {
    left: 0;
  }

  .warp-line-end::before {
    right: 0;
  }

  /*
   * the grip straddles the column boundary, and the reed inside it is the divider the
   * head would draw anyway. currentColor, because a gradient cannot transition.
   */
  .reed-grip {
    position: absolute;
    inset-block: 0;
    right: -4px;
    z-index: var(--z-grip);
    width: 8px;
    color: var(--color-reed-lit);
    cursor: col-resize;
    touch-action: none;
    transition: color var(--dur-instant) var(--ease-beat);
  }

  .reed-grip::before {
    content: '';
    position: absolute;
    inset-block: 0;
    left: 4px;
    width: 1px;
    background-image: repeating-linear-gradient(
      0deg,
      currentColor 0 var(--reed-tick),
      transparent var(--reed-tick) var(--reed-pitch)
    );
  }

  .reed-grip:hover,
  .reed-grip:focus-visible,
  .reed-grip[data-dragging] {
    color: var(--color-indigo);
  }

  /* an unwoven warp: the threads sit in the reed and no weft has arrived */
  .reed-warp {
    background-image: repeating-linear-gradient(
      90deg,
      var(--color-reed) 0 var(--reed-tick),
      transparent var(--reed-tick) var(--reed-pitch)
    );
  }

  /* only the loading state moves */
  .reed-warp-beat {
    animation: beat 1.2s var(--ease-glide) infinite;
  }

  /*
   * the cover layer is attached to the content, so it arrives at the edge and hides
   * the reed at the end of the list. a short list needs no cover: the scrollable area
   * is then the padding box and the two layers land together.
   */
  .reed-scroll {
    background-image:
      linear-gradient(var(--color-raised), var(--color-raised)),
      repeating-linear-gradient(
        90deg,
        var(--color-reed-lit) 0 var(--reed-tick),
        transparent var(--reed-tick) var(--reed-pitch)
      );
    background-position: bottom;
    background-size: 100% 2px;
    background-repeat: no-repeat;
    background-attachment: local, scroll;
    scrollbar-width: thin;
    scrollbar-color: var(--color-reed-lit) transparent;
  }

  /* the standard properties above win where supported, so these reach safari only */
  .reed-scroll::-webkit-scrollbar {
    width: 8px;
    height: 8px;
  }

  .reed-scroll::-webkit-scrollbar-track {
    background-color: transparent;
  }

  .reed-scroll::-webkit-scrollbar-thumb {
    background-color: var(--color-reed-lit);
  }

  .reed-scroll::-webkit-scrollbar-thumb:hover {
    background-color: var(--color-indigo);
  }

  .beat {
    animation: beat 1.6s var(--ease-glide) infinite;
  }

  /*
   * plot writes font-family, font-size and fill on the svg as presentation
   * attributes, and any stylesheet rule outranks those. it names every axis part
   * with an aria-label, which is the only stable handle on the generated markup.
   */
  .sley-plot {
    color: var(--color-weft-dim);
    font-family: var(--font-data);
    font-size: var(--ui-text);
    /*
     * the halo behind a crosshair readout and the fill of a tip. plot declares it
     * white from a <style> inside the svg, and an unlayered rule outranks a layered
     * one whatever the specificity says, so this one has to shout.
     */
    --plot-background: var(--color-raised) !important;
  }

  .sley-plot [aria-label$='grid'] {
    color: var(--color-reed);
    stroke-opacity: 1;
  }

  .sley-plot [aria-label$='axis tick'] {
    color: var(--color-reed-lit);
  }

  .sley-plot [aria-label$='tick label'] {
    color: var(--color-weft-dim);
  }

  /* an axis label is a human phrase, so it leaves the data face */
  .sley-plot [aria-label$='axis label'] {
    color: var(--color-weft-dim);
    font-family: var(--font-ui);
  }

  .sley-plot [aria-label='crosshair rule'] {
    color: var(--color-reed-lit);
    stroke-opacity: 1;
  }

  .sley-plot [aria-label='crosshair text'] {
    color: var(--color-weft);
  }

  /*
   * a readout stands where a tick label already is, and the halo behind it outlines
   * each glyph rather than covering a line, so the tick reads through the gaps. the
   * readout carries the exact value, so the axis stands down while it is showing. plot
   * renders the readout only while the pointer is in the plot, which is the condition.
   */
  .sley-plot:has([aria-label='crosshair text'] text) [aria-label$='tick label'] {
    opacity: 0;
    transition: opacity var(--dur-instant) var(--ease-beat);
  }

  /* one weft thread travelling across the cloth, and each series follows the one above it */
  .sley-plot .reed-draw {
    stroke-dasharray: var(--draw);
    animation: draw var(--dur-overlay) var(--ease-beat) var(--draw-delay) both;
  }

  /* the cloth builds column by column, each bar standing up off the axis */
  .sley-plot .reed-build {
    transform-origin: 0 var(--build-base);
    animation: build var(--dur-overlay) var(--ease-beat) var(--build-delay) both;
  }

  .reed-brush-field {
    fill: transparent;
    cursor: crosshair;
  }

  /* a brush window is what the reader chose, so it takes the selvedge wash */
  .reed-brush {
    fill: var(--color-indigo-wash);
    stroke: var(--color-indigo);
    stroke-width: 1px;
    pointer-events: none;
  }
}

@keyframes beat {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.25;
  }
}

@keyframes draw {
  from {
    stroke-dashoffset: var(--draw);
  }
}

@keyframes build {
  from {
    transform: scaleY(0);
  }
}

@keyframes fade {
  from {
    opacity: 0;
  }
}

@keyframes fade-out {
  to {
    opacity: 0;
  }
}

@keyframes rise {
  from {
    opacity: 0;
    transform: translateY(-6px) scale(0.99);
  }
}

@keyframes rise-out {
  to {
    opacity: 0;
    transform: translateY(-6px) scale(0.99);
  }
}

/* the panel arrives from the edge that holds it, which sets --slide-from */
@keyframes slide {
  from {
    opacity: 0;
    transform: translateX(var(--slide-from));
  }
}

/* it leaves the way it came, and it leaves faster, on the exit curve */
@keyframes slide-out {
  to {
    opacity: 0;
    transform: translateX(var(--slide-from));
  }
}

@media (prefers-reduced-motion: reduce) {
  .beat,
  .reed-warp-beat {
    animation: none;
  }
}

import { clsx, type ClassValue } from 'clsx'
import { twMerge } from 'tailwind-merge'

/*
 * the stylesheet order decides between two utilities for one property, so a plain
 * join lets an override fail with no message.
 */
export function cx(...classes: ClassValue[]) {
  return twMerge(clsx(classes))
}

import type { ComponentPropsWithoutRef } from 'react'
import { cx } from '@/lib/cx'

export type ButtonVariant = 'default' | 'primary' | 'danger' | 'quiet'

interface ButtonProps extends ComponentPropsWithoutRef<'button'> {
  readonly variant?: ButtonVariant
}

const VARIANT: Record<ButtonVariant, string> = {
  default: 'ctl',
  primary: 'border border-indigo bg-indigo text-ground hover:bg-indigo/90',
  danger: 'border border-madder bg-madder text-ground hover:bg-madder/90',
  quiet: 'text-weft-dim hover:text-weft',
}

export const Button = ({ variant = 'default', type = 'button', className, ...props }: ButtonProps) => (
  <button
    type={type}
    className={cx(
      'inline-flex h-(--ctl-h) cursor-pointer items-center justify-center gap-1.5 px-(--cell-x) transition-colors duration-(--dur-instant) ease-(--ease-beat) disabled:cursor-not-allowed disabled:opacity-50',
      VARIANT[variant],
      className,
    )}
    {...props}
  />
)

import * as Plot from '@observablehq/plot'
import { useEffect, useRef, useState, type ReactNode } from 'react'
import { attachBrush } from '@/components/ui/chart/brush'
import { drawBars, drawLines } from '@/components/ui/chart/motion'
import { EmptyState } from '@/components/ui/empty-state/EmptyState'
import { cx } from '@/lib/cx'

/* the stylesheet reaches the generated svg through this one name */
const PLOT_CLASS = 'sley-plot'

/*
 * plot takes a margin as a number, so it cannot read a density token. these are
 * sized for the widest tick label at the comfortable text size, which leaves a
 * denser mode a little slack and spares every chart a re-render on the knob.
 */
const MARGIN = { marginTop: 16, marginRight: 16, marginBottom: 40, marginLeft: 56 }

/* plot points a quantitative axis label with an arrow glyph, and no interface string here carries one */
const AXIS = { labelArrow: 'none' } as const

export type ChartOptions = Omit<Plot.PlotOptions, 'width' | 'height' | 'className'>

export interface ChartProps<X> {
  readonly title: string
  /* the unit belongs in the header, the way a column head carries it and a cell never does */
  readonly unit?: string
  /* hold this stable, or every parent render tears the plot down and builds it again */
  readonly options: ChartOptions
  readonly height?: number
  readonly loading?: boolean
  /* a chart cannot read the caller's marks, so an empty result is stated and never derived */
  readonly empty?: boolean
  readonly emptyMessage?: string
  readonly actions?: ReactNode
  /*
   * a drag reports a range of the x scale, and an arrow key on the plot moves one edge
   * of one by a tick of that axis. a single click reports null, and so does escape.
   */
  readonly onBrush?: (range: readonly [X, X] | null) => void
  /* the window the chart paints. hold it in your own state, the way a table's selection works. */
  readonly brush?: readonly [X, X] | null
  readonly className?: string
}

export function Chart<X = Date>({
  title,
  unit,
  options,
  height = 260,
  loading = false,
  empty = false,
  emptyMessage = 'No data in this range.',
  actions,
  onBrush,
  brush = null,
  className,
}: ChartProps<X>) {
  /* the frame is measured rather than the host, because the host leaves while a state shows */
  const frame = useRef<HTMLDivElement>(null)
  const host = useRef<HTMLDivElement>(null)
  const [width, setWidth] = useState(0)

  /* the plot outlives a change of handler, so the newest one is read at report time */
  const report = useRef(onBrush)
  report.current = onBrush

  const window = useRef<{ show: (range: readonly [X, X] | null) => void } | null>(null)

  /* the plot is built in an effect that does not watch the window, so the first paint reads it here */
  const brushed = useRef(brush)
  brushed.current = brush

  /* the lines draw in once. a resize rebuilds the plot, and replaying it there reads as a glitch. */
  const drawn = useRef(false)

  /* a rebuild takes the focused field down with it, so a resize would strand the keyboard */
  const held = useRef(false)

  /* loading wins: a chart still waiting on a fetch has nothing to call empty yet */
  const showEmpty = empty && !loading
  const plotting = !loading && !showEmpty

  useEffect(() => {
    window.current?.show(brush)
  }, [brush])

  useEffect(() => {
    const node = frame.current
    if (!node) return undefined

    const observer = new ResizeObserver(([entry]) => setWidth(Math.floor(entry.contentRect.width)))
    observer.observe(node)
    return () => observer.disconnect()
  }, [])

  useEffect(() => {
    const node = host.current
    if (!node || width === 0) return undefined

    const margins = { ...MARGIN, ...options }
    const plot = Plot.plot({
      ...margins,
      ariaLabel: title,
      x: { ...AXIS, ...options.x },
      y: { ...AXIS, ...options.y },
      width,
      height,
      className: PLOT_CLASS,
    })
    node.append(plot)

    const svg = plot instanceof SVGSVGElement ? plot : plot.querySelector('svg')
    if (svg && !drawn.current) {
      drawn.current = true
      drawLines(svg)
      drawBars(svg)
    }

    const scale = plot.scale('x')
    if (!svg || !scale?.invert) return () => plot.remove()

    /* plot types every scale value as any, so both readings are named here once */
    const toValue: (px: number) => X = scale.invert.bind(scale)
    const toPixel: (value: X) => number = scale.apply.bind(scale)

    const handle = attachBrush(
      svg,
      {
        left: margins.marginLeft,
        right: width - margins.marginRight,
        top: margins.marginTop,
        bottom: height - margins.marginBottom,
      },
      { toValue, toPixel },
      (range) => report.current?.(range),
    )
    handle.show(brushed.current)
    if (held.current) handle.restore()
    window.current = handle

    return () => {
      held.current = handle.focused()
      window.current = null
      handle.destroy()
      plot.remove()
    }
  }, [title, options, width, height, plotting])

  return (
    <section className={cx('@container border border-reed bg-raised', className)}>
      <header className="flex items-center justify-between gap-(--stack) border-b border-reed px-(--cell-x) py-(--stack)">
        <h2 className="inline-flex items-baseline gap-1.5 font-medium">
          <span>{title}</span>
          {unit && <span className="font-data font-normal text-weft-faint">{unit}</span>}
        </h2>
        {actions && <div className="flex items-center gap-(--stack)">{actions}</div>}
      </header>

      <div ref={frame} aria-busy={loading} className="px-(--cell-x) py-(--stack)">
        {plotting && <div ref={host} />}
        {loading && <div className="reed-warp reed-warp-beat" style={{ height }} />}
        {showEmpty && (
          <div style={{ height }}>
            <EmptyState title={emptyMessage} className="h-full" />
          </div>
        )}
      </div>
    </section>
  )
}

const SVG_NS = 'http://www.w3.org/2000/svg'

/* a click that travels less than this is a click, and a click clears the window */
const MIN_DRAG = 3

/* the resize grip moves 8px a press, and a step under that reads as nothing happening */
const MIN_STEP = 8

const KEYS = new Set(['ArrowLeft', 'ArrowRight', 'Home', 'End', 'Escape'])

/* the field is the only surface that can announce the keys, so its name carries them */
const HOW = 'Move an edge with the arrow keys. Escape clears.'

export interface BrushFrame {
  readonly left: number
  readonly right: number
  readonly top: number
  readonly bottom: number
}

/*
 * plot re-renders a whole svg on every change, so the brush layer is appended to the
 * node it belongs to and dies with it. the caller owns no listener and no cleanup
 * beyond the teardown returned here.
 */
export interface BrushScale<T> {
  readonly toValue: (px: number) => T
  readonly toPixel: (value: T) => number
}

/* one press is one tick of the x axis: a distance the scale already draws for the reader */
function stepOf(svg: SVGSVGElement, frame: BrushFrame) {
  const ticks = svg.querySelectorAll<SVGGraphicsElement>('[aria-label="x-axis tick"] path')
  const xs = Array.from(ticks, (tick) => tick.transform.baseVal.consolidate()?.matrix.e ?? 0).sort(
    (a, b) => a - b,
  )
  const gaps = xs.slice(1).map((x, index) => x - xs[index])
  if (gaps.length === 0) return (frame.right - frame.left) / 20

  gaps.sort((a, b) => a - b)
  return Math.max(MIN_STEP, gaps[Math.floor(gaps.length / 2)])
}

export function attachBrush<T>(
  svg: SVGSVGElement,
  frame: BrushFrame,
  scale: BrushScale<T>,
  report: (range: readonly [T, T] | null) => void,
) {
  const height = frame.bottom - frame.top
  const step = stepOf(svg, frame)
  const named = svg.getAttribute('aria-label')

  const field = document.createElementNS(SVG_NS, 'rect')
  field.setAttribute('class', 'reed-brush-field')
  field.setAttribute('x', String(frame.left))
  field.setAttribute('y', String(frame.top))
  field.setAttribute('width', String(frame.right - frame.left))
  field.setAttribute('height', String(height))
  field.setAttribute('tabindex', '0')
  field.setAttribute('aria-label', named ? `Select a range on ${named}. ${HOW}` : `Select a range. ${HOW}`)

  const selection = document.createElementNS(SVG_NS, 'rect')
  selection.setAttribute('class', 'reed-brush')
  selection.setAttribute('aria-hidden', 'true')
  selection.setAttribute('y', String(frame.top))
  selection.setAttribute('height', String(height))
  selection.setAttribute('width', '0')

  /* the window tints the data rather than hiding it, so it goes under every mark */
  svg.insertBefore(selection, svg.firstChild)
  svg.append(field)

  let anchor = 0
  let edge = 0
  let dragging = false
  let live = false

  /* raised for the one paint that answers a report, and read by show below */
  let reported = false

  const xOf = (event: PointerEvent) => clampX(event.clientX - svg.getBoundingClientRect().left)

  const clampX = (value: number) => Math.max(frame.left, Math.min(frame.right, value))

  const paint = (from: number, to: number) => {
    selection.setAttribute('x', String(Math.min(from, to)))
    selection.setAttribute('width', String(Math.abs(to - from)))
  }

  const clear = () => {
    live = false
    reported = false
    paint(0, 0)
  }

  const onDown = (event: PointerEvent) => {
    dragging = true
    anchor = xOf(event)
    edge = anchor
    paint(anchor, anchor)
    field.setPointerCapture(event.pointerId)
  }

  const onMove = (event: PointerEvent) => {
    if (!dragging) return
    edge = xOf(event)
    paint(anchor, edge)
  }

  const onRelease = () => {
    if (!dragging) return
    dragging = false

    if (Math.abs(edge - anchor) < MIN_DRAG) {
      clear()
      report(null)
      return
    }
    live = true
    reported = true
    const from = Math.min(anchor, edge)
    const to = Math.max(anchor, edge)
    report([scale.toValue(from), scale.toValue(to)])
  }

  /*
   * a drag anchors one edge and carries the other, and the keys do the same thing one
   * step at a time. the first press has nothing to anchor, so it takes the edge of the
   * frame it moves away from.
   */
  const moveEdge = (to: number) => {
    edge = clampX(to)
    live = true
    reported = true
    paint(anchor, edge)
    report([scale.toValue(Math.min(anchor, edge)), scale.toValue(Math.max(anchor, edge))])
  }

  const onKey = (event: KeyboardEvent) => {
    if (!KEYS.has(event.key)) return
    event.preventDefault()

    if (event.key === 'Escape') {
      if (!live) return
      clear()
      report(null)
      return
    }

    const back = event.key === 'ArrowLeft' || event.key === 'Home'
    if (!live) {
      anchor = back ? frame.right : frame.left
      edge = anchor
    }

    if (event.key === 'Home') moveEdge(frame.left)
    else if (event.key === 'End') moveEdge(frame.right)
    else moveEdge(edge + (back ? -step : step))
  }

  field.addEventListener('pointerdown', onDown)
  field.addEventListener('pointermove', onMove)
  field.addEventListener('lostpointercapture', onRelease)
  field.addEventListener('keydown', onKey)

  return {
    /*
     * the caller owns the range, so a re-render paints the window it still holds
     * rather than dropping it and leaving the two out of step.
     */
    show(range: readonly [T, T] | null) {
      if (!range) {
        clear()
        return
      }
      const from = clampX(scale.toPixel(range[0]))
      const to = clampX(scale.toPixel(range[1]))
      live = true
      paint(from, to)

      /*
       * a caller may widen what it was given, and the demo here rounds a range out to whole
       * days. taking the moving edge from that value would add the widening to the next key
       * press on top of the step, so the paint that answers a report moves no edge.
       */
      if (reported) {
        reported = false
        return
      }

      /* the moving edge stays the one the reader is moving, or the next key press reverses */
      const forward = edge >= anchor
      anchor = forward ? from : to
      edge = forward ? to : from
    },
    focused() {
      return document.activeElement === field
    },
    /* a rebuild draws a new field, and the reader is still on the old one */
    restore() {
      field.focus({ preventScroll: true })
    },
    destroy() {
      field.removeEventListener('pointerdown', onDown)
      field.removeEventListener('pointermove', onMove)
      field.removeEventListener('lostpointercapture', onRelease)
      field.removeEventListener('keydown', onKey)
      selection.remove()
      field.remove()
    },
  }
}

import * as Plot from '@observablehq/plot'

export interface CrosshairXOptions<T> {
  readonly x: Plot.ChannelValue
  readonly y?: Plot.ChannelValue
  readonly formatX?: (row: T) => string
  readonly formatY?: (row: T) => string
  readonly maxRadius?: number
}

const RULE = { inset: -6, stroke: 'currentColor', strokeOpacity: 0.2 } as const

/* the halo outlines each glyph against the surface the chart is drawn on */
const READOUT = { fill: 'currentColor', stroke: 'var(--plot-background)', strokeWidth: 5 } as const

/* plot names the group of rendered elements from a field the class type does not declare */
const named = <M extends object>(mark: M, ariaLabel: string) => Object.assign(mark, { ariaLabel })

/*
 * plot's own crosshair derives each readout from its source channel through an
 * initializer, and an initializer's channels are merged over the declared ones, so a
 * text the caller passes is discarded and a date reads as a full iso stamp. the pairs
 * are composed here from the same public pointer transform instead.
 */
export function crosshairX<T>(data: readonly T[], options: CrosshairXOptions<T>) {
  const { x, y, formatX, formatY, maxRadius } = options
  const point = { px: x, py: y, maxRadius }

  const acrossRule = named(Plot.ruleX(data, Plot.pointerX({ ...point, x, ...RULE })), 'crosshair rule')

  const acrossText = named(
    Plot.text(
      data,
      Plot.pointerX({ ...point, x, text: formatX ?? x, dy: 9, frameAnchor: 'bottom', lineAnchor: 'top', ...READOUT }),
    ),
    'crosshair text',
  )

  if (y === undefined) return Plot.marks(acrossRule, acrossText)

  const downRule = named(Plot.ruleY(data, Plot.pointerX({ ...point, y, ...RULE })), 'crosshair rule')

  const downText = named(
    Plot.text(
      data,
      Plot.pointerX({ ...point, y, text: formatY ?? y, dx: -9, frameAnchor: 'left', textAnchor: 'end', ...READOUT }),
    ),
    'crosshair text',
  )

  /* both rules go under both readouts, or the horizontal rule crosses the label at the foot */
  return Plot.marks(acrossRule, downRule, acrossText, downText)
}

/*
 * largest triangle three buckets. a line with more points than the frame has pixels
 * spends layout time on detail nobody can resolve, and taking every nth point flattens
 * a spike that falls in the gap. this keeps whichever point in a bucket makes the widest
 * triangle with the point already kept and the bucket ahead, which follows the shape of the
 * line. the extremes are not a guarantee: where a bucket boundary splits a peak, the peak
 * can lose to its own shoulder.
 */
export function downsample<T>(
  rows: readonly T[],
  x: (row: T) => number,
  y: (row: T) => number,
  target: number,
): readonly T[] {
  if (rows.length <= target || target < 3) return rows

  const last = rows.length - 1
  const every = (rows.length - 2) / (target - 2)
  const kept: T[] = [rows[0]]
  let anchor = 0

  for (let bucket = 0; bucket < target - 2; bucket++) {
    const start = Math.floor(bucket * every) + 1
    const end = Math.floor((bucket + 1) * every) + 1

    /* the bucket ahead stands in for its own points as one centre of mass */
    const aheadEnd = Math.min(Math.floor((bucket + 2) * every) + 1, rows.length)
    let aheadX = 0
    let aheadY = 0
    for (let i = end; i < aheadEnd; i++) {
      aheadX += x(rows[i])
      aheadY += y(rows[i])
    }
    aheadX /= aheadEnd - end
    aheadY /= aheadEnd - end

    const anchorX = x(rows[anchor])
    const anchorY = y(rows[anchor])
    let widest = -1
    let best = start

    for (let i = start; i < end; i++) {
      const area = Math.abs(
        (anchorX - aheadX) * (y(rows[i]) - anchorY) - (anchorX - x(rows[i])) * (aheadY - anchorY),
      )
      if (area > widest) {
        widest = area
        best = i
      }
    }
    kept.push(rows[best])
    anchor = best
  }

  kept.push(rows[last])
  return kept
}

/*
 * a dash cannot be given the length of its own path from a stylesheet, so the length
 * is measured here and handed to the animation as a custom property.
 */
export function drawLines(svg: SVGSVGElement) {
  const paths = svg.querySelectorAll<SVGPathElement>('g[aria-label="line"] path')

  paths.forEach((path, index) => {
    path.style.setProperty('--draw', `${path.getTotalLength()}px`)
    path.style.setProperty('--draw-delay', `calc(var(--dur-instant) * ${index})`)
    path.classList.add('reed-draw')
  })

  return paths.length
}

/*
 * a bar grows out of the axis rather than out of its own box, so a stacked column stays
 * whole on the way up. every rect scales about the same baseline, which is the lowest
 * edge any of them reaches.
 */
export function drawBars(svg: SVGSVGElement) {
  const rects = [...svg.querySelectorAll<SVGRectElement>('g[aria-label="bar"] rect')]
  if (rects.length === 0) return 0

  const base = Math.max(...rects.map((rect) => rect.y.baseVal.value + rect.height.baseVal.value))
  const columns = [...new Set(rects.map((rect) => rect.x.baseVal.value))].sort((left, right) => left - right)
  const order = new Map(columns.map((x, index) => [x, index]))

  for (const rect of rects) {
    const index = order.get(rect.x.baseVal.value) ?? 0
    rect.style.setProperty('--build-base', `${base}px`)
    /* the sweep across the columns fits inside one --dur-instant, whatever the count */
    rect.style.setProperty('--build-delay', `calc(var(--dur-instant) * ${index / columns.length})`)
    rect.classList.add('reed-build')
  }

  return rects.length
}

